Object.assign(SNIP,{});PRESET_NOTES["l46"]={"Ví dụ: LIS bằng quy hoạch động O(n²)": "dp = 1, 1, 1, 2, 2, 3, 4, 4. Ví dụ dp[5] = 3 (a[5] = 7 nối sau 2, 5 hoặc 2, 3). Đáp án là ô lớn nhất, không nhất thiết là ô cuối.", "Ví dụ: Mảng đuôi nhỏ nhất": "d thay đổi: [10] → [9] → [2] → [2,5] → [2,3] → [2,3,7] → [2,3,7,101] → [2,3,7,18]. Mỗi phần tử tốn một lần tìm kiếm nhị phân: O(n log n).", "Ví dụ: Truy vết để in dãy con": "Đi ngược từ ô có dp lớn nhất theo truoc: 101 → 7 → 5 → 2, in ngược lại thành 2 5 7 101.", "Ví dụ: Dãy con không giảm dùng upper_bound": "Tăng ngặt dài nhất là 2 (1, 3 hoặc 1, 2); không giảm dài nhất là 4 (1, 2, 2, 2). Khác nhau đúng một chữ: lower_bound hay upper_bound.", "Lỗi: tưởng mảng đuôi là dãy con": "In 1 4 5, nhưng 1 đứng sau 5 trong a nên 1, 4, 5 không phải dãy con. Độ dài 3 thì đúng; muốn in dãy con phải lưu thêm chỉ số và phần tử trước, rồi truy vết."};EX_HINTS["l46"]=[["Giống LIS O(n²), chỉ thay “độ dài” bằng “tổng”: dp[i] = a[i] + max dp[j] với j < i, a[j] < a[i].", "Không có j phù hợp thì dp[i] = a[i].", "Mẹo mảng đuôi không dùng được ở đây; n ≤ 3000 nên O(n²) là vừa. Tổng tới 3·10^12: long long."], ["Giữ d tăng dần: d[k] là đuôi nhỏ nhất của dãy con tăng dài k + 1.", "lower_bound tìm ô đầu tiên ≥ x. Không có thì push_back(x), có thì ghi đè bằng x.", "Tăng ngặt nên dùng lower_bound; với upper_bound bạn sẽ đếm cả dãy có phần tử bằng nhau."], ["Sắp theo w tăng dần thì chuỗi lồng nhau là một dãy con có h tăng ngặt: bài trở thành LIS trên h.", "Hai phong bì cùng w không lồng được. Sắp chúng theo h GIẢM dần để LIS không lấy được cả hai.", "LIS bằng mảng đuôi O(n log n); n = 10^5 nên O(n²) quá chậm."]];
/* ===================== BÀI 46 · Dãy con tăng dài nhất (LIS) ===================== */
/* Bài 46 · Dãy con tăng dài nhất (LIS)
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR46=[{label:"Ví dụ: LIS bằng quy hoạch động O(n²)",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[8] = {10, 9, 2, 5, 3, 7, 101, 18};\n    int n = 8, dp[8], best = 0;\n    for (int i = 0; i < n; i++) {\n        dp[i] = 1;                     // chỉ có a[i]\n        for (int j = 0; j < i; j++)\n            if (a[j] < a[i] && dp[j] + 1 > dp[i]) dp[i] = dp[j] + 1;   // nối a[i] sau dãy kết thúc tại a[j]\n        best = max(best, dp[i]);\n    }\n    cout << best << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i","j"]},{type:"cells",of:"dp",ptr:["i","j"]}],py:{code:"a = [10, 9, 2, 5, 3, 7, 101, 18]\nn = len(a)\ndp = [1] * n                           # chỉ có a[i]\nfor i in range(n):\n    for j in range(i):\n        if a[j] < a[i] and dp[j] + 1 > dp[i]:\n            dp[i] = dp[j] + 1          # nối a[i] sau dãy kết thúc tại a[j]\nprint(max(dp))"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 10, 9, 2, 5, 3, 7, 101, 18 };\n        int n = a.Length, best = 0;\n        int[] dp = new int[n];\n        for (int i = 0; i < n; i++)\n        {\n            dp[i] = 1;                         // chỉ có a[i]\n            for (int j = 0; j < i; j++)\n                if (a[j] < a[i] && dp[j] + 1 > dp[i]) dp[i] = dp[j] + 1;   // nối a[i] sau dãy kết thúc tại a[j]\n            best = Math.Max(best, dp[i]);\n        }\n        Console.WriteLine(best);\n    }\n}"}},{label:"Ví dụ: Mảng đuôi nhỏ nhất",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> a = {10, 9, 2, 5, 3, 7, 101, 18};\n    vector<int> d;                     // d[k]: đuôi nhỏ nhất của dãy tăng dài k + 1\n    for (int i = 0; i < (int)a.size(); i++) {\n        int k = lower_bound(d.begin(), d.end(), a[i]) - d.begin();   // ô đầu tiên >= a[i]\n        if (k == (int)d.size()) d.push_back(a[i]);   // nối dài dãy dài nhất\n        else d[k] = a[i];                            // cùng độ dài, đuôi nhỏ hơn\n    }\n    cout << d.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"cells",of:"d",ptr:["k"]}],py:{code:"from bisect import bisect_left\n\na = [10, 9, 2, 5, 3, 7, 101, 18]\nd = []                                 # d[k]: đuôi nhỏ nhất của dãy tăng dài k + 1\nfor i in range(len(a)):\n    k = bisect_left(d, a[i])           # ô đầu tiên >= a[i]\n    if k == len(d):\n        d.append(a[i])                 # nối dài dãy dài nhất\n    else:\n        d[k] = a[i]                    # cùng độ dài, đuôi nhỏ hơn\nprint(len(d))"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static int LowerBound(List<int> d, int x)   // ô đầu tiên >= x (d tăng dần)\n    {\n        int lo = 0, hi = d.Count;\n        while (lo < hi)\n        {\n            int mid = (lo + hi) / 2;\n            if (d[mid] < x) lo = mid + 1;\n            else hi = mid;\n        }\n        return lo;\n    }\n\n    static void Main()\n    {\n        int[] a = { 10, 9, 2, 5, 3, 7, 101, 18 };\n        var d = new List<int>();               // d[k]: đuôi nhỏ nhất của dãy tăng dài k + 1\n        for (int i = 0; i < a.Length; i++)\n        {\n            int k = LowerBound(d, a[i]);       // ô đầu tiên >= a[i]\n            if (k == d.Count) d.Add(a[i]);     // nối dài dãy dài nhất\n            else d[k] = a[i];                  // cùng độ dài, đuôi nhỏ hơn\n        }\n        Console.WriteLine(d.Count);\n    }\n}"}},{label:"Ví dụ: Truy vết để in dãy con",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[8] = {10, 9, 2, 5, 3, 7, 101, 18};\n    int n = 8, dp[8], truoc[8], cuoi = 0;\n    for (int i = 0; i < n; i++) {\n        dp[i] = 1;\n        truoc[i] = -1;                 // không có phần tử trước\n        for (int j = 0; j < i; j++)\n            if (a[j] < a[i] && dp[j] + 1 > dp[i]) {\n                dp[i] = dp[j] + 1;\n                truoc[i] = j;          // nhớ đã nối sau j\n            }\n        if (dp[i] > dp[cuoi]) cuoi = i;\n    }\n    int kq[8], m = 0;\n    for (int i = cuoi; i != -1; i = truoc[i]) kq[m++] = a[i];   // đi ngược\n    for (int k = m - 1; k >= 0; k--) cout << kq[k] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["i"]},{type:"cells",of:"truoc",ptr:["i"]}],py:{code:"a = [10, 9, 2, 5, 3, 7, 101, 18]\nn = len(a)\ndp = [1] * n\ntruoc = [-1] * n                       # -1: không có phần tử trước\ncuoi = 0\nfor i in range(n):\n    for j in range(i):\n        if a[j] < a[i] and dp[j] + 1 > dp[i]:\n            dp[i] = dp[j] + 1\n            truoc[i] = j               # nhớ đã nối sau j\n    if dp[i] > dp[cuoi]:\n        cuoi = i\nkq = []\ni = cuoi\nwhile i != -1:                         # đi ngược\n    kq.append(a[i])\n    i = truoc[i]\nprint(*reversed(kq))"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 10, 9, 2, 5, 3, 7, 101, 18 };\n        int n = a.Length, cuoi = 0;\n        int[] dp = new int[n], truoc = new int[n];\n        for (int i = 0; i < n; i++)\n        {\n            dp[i] = 1;\n            truoc[i] = -1;                     // không có phần tử trước\n            for (int j = 0; j < i; j++)\n                if (a[j] < a[i] && dp[j] + 1 > dp[i])\n                {\n                    dp[i] = dp[j] + 1;\n                    truoc[i] = j;              // nhớ đã nối sau j\n                }\n            if (dp[i] > dp[cuoi]) cuoi = i;\n        }\n        var kq = new List<int>();\n        for (int i = cuoi; i != -1; i = truoc[i]) kq.Add(a[i]);   // đi ngược\n        kq.Reverse();\n        Console.WriteLine(string.Join(\" \", kq));\n    }\n}"}},{label:"Ví dụ: Dãy con không giảm dùng upper_bound",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> a = {3, 3, 1, 3, 2, 2, 2};\n    vector<int> d1, d2;\n    for (int x : a) {\n        auto p = lower_bound(d1.begin(), d1.end(), x);    // tăng ngặt\n        if (p == d1.end()) d1.push_back(x); else *p = x;\n        auto q = upper_bound(d2.begin(), d2.end(), x);    // không giảm: được bằng nhau\n        if (q == d2.end()) d2.push_back(x); else *q = x;\n    }\n    cout << d1.size() << \" \" << d2.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"d1"},{type:"cells",of:"d2"}],py:{label:"Ví dụ: Dãy con không giảm dùng bisect_right",code:"from bisect import bisect_left, bisect_right\n\na = [3, 3, 1, 3, 2, 2, 2]\nd1, d2 = [], []\nfor x in a:\n    k = bisect_left(d1, x)             # tăng ngặt\n    if k == len(d1): d1.append(x)\n    else: d1[k] = x\n    k = bisect_right(d2, x)            # không giảm: được bằng nhau\n    if k == len(d2): d2.append(x)\n    else: d2[k] = x\nprint(len(d1), len(d2))",note:"Tăng ngặt dài nhất là 2 (1, 3 hoặc 1, 2); không giảm dài nhất là 4 (1, 2, 2, 2). Khác nhau đúng một chữ: bisect_left hay bisect_right."},cs:{label:"Ví dụ: Dãy con không giảm: tìm ô đầu tiên > x",code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static int Tim(List<int> d, int x, bool lonHonHan)\n    {\n        int lo = 0, hi = d.Count;\n        while (lo < hi)\n        {\n            int mid = (lo + hi) / 2;\n            if (d[mid] < x || (lonHonHan && d[mid] == x)) lo = mid + 1;\n            else hi = mid;\n        }\n        return lo;\n    }\n\n    static void Main()\n    {\n        int[] a = { 3, 3, 1, 3, 2, 2, 2 };\n        var d1 = new List<int>();\n        var d2 = new List<int>();\n        foreach (int x in a)\n        {\n            int k = Tim(d1, x, false);         // tăng ngặt: ô đầu tiên >= x\n            if (k == d1.Count) d1.Add(x); else d1[k] = x;\n            k = Tim(d2, x, true);              // không giảm: ô đầu tiên > x\n            if (k == d2.Count) d2.Add(x); else d2[k] = x;\n        }\n        Console.WriteLine(d1.Count + \" \" + d2.Count);\n    }\n}",note:"Tăng ngặt dài nhất là 2 (1, 3 hoặc 1, 2); không giảm dài nhất là 4 (1, 2, 2, 2). Khác nhau đúng ở phép so sánh trong tìm kiếm nhị phân: ô đầu tiên ≥ x hay > x."}},{label:"Lỗi: tưởng mảng đuôi là dãy con",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> a = {3, 4, 5, 1};\n    vector<int> d;\n    for (int x : a) {\n        auto p = lower_bound(d.begin(), d.end(), x);\n        if (p == d.end()) d.push_back(x); else *p = x;\n    }\n    for (int x : d) cout << x << \" \";   // SAI nếu đề yêu cầu in dãy con\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"cells",of:"d"}],py:{code:"from bisect import bisect_left\n\na = [3, 4, 5, 1]\nd = []\nfor x in a:\n    k = bisect_left(d, x)\n    if k == len(d): d.append(x)\n    else: d[k] = x\nprint(*d)                              # SAI nếu đề yêu cầu in dãy con"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static int LowerBound(List<int> d, int x)   // ô đầu tiên >= x (d tăng dần)\n    {\n        int lo = 0, hi = d.Count;\n        while (lo < hi)\n        {\n            int mid = (lo + hi) / 2;\n            if (d[mid] < x) lo = mid + 1;\n            else hi = mid;\n        }\n        return lo;\n    }\n\n    static void Main()\n    {\n        int[] a = { 3, 4, 5, 1 };\n        var d = new List<int>();\n        foreach (int x in a)\n        {\n            int k = LowerBound(d, x);\n            if (k == d.Count) d.Add(x); else d[k] = x;\n        }\n        Console.WriteLine(string.Join(\" \", d));   // SAI nếu đề yêu cầu in dãy con\n    }\n}"}}];
const sim46=makeSim2(document.getElementById("sim-l46"),{id:"s46",presets:PR46});
makeEx2(document.getElementById("ex-l46"),sim46,[{t:"Tháp tăng dần nặng nhất",d:"Đầu vào: n (1 ≤ n ≤ 3000) và n số nguyên dương aᵢ (≤ 10^9). Đầu ra: tổng lớn nhất của một dãy con tăng ngặt.",tests:[{in:"7\n1 101 2 3 100 4 5",out:"106"},{in:"4\n3 4 5 10",out:"22"},{in:"4\n10 5 4 3",out:"10"},{in:"1\n7",out:"7"},{in:"3\n5 5 5",out:"5"},{in:"5\n1000000000 1 999999999 2 1000000000",out:"2000000000"},{in:"80\n1 38 75 11 48 85 21 58 95 31 68 4 41 78 14 51 88 24 61 98 34 71 7 44 81 17 54 91 27 64 101 37 74 10 47 84 20 57 94 30 67 3 40 77 13 50 87 23 60 97 33 70 6 43 80 16 53 90 26 63 100 36 73 9 46 83 19 56 93 29 66 2 39 76 12 49 86 22 59 96",out:"822"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> a(n), dp(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    // dp[i]: tổng lớn nhất của dãy con tăng kết thúc tại a[i]\n    long long best = 0;\n    cout << best << \"\\n\";\n    return 0;\n}",py:{start:"n = int(input())\na = list(map(int, input().split()))\ndp = [0] * n                   # dp[i]: tổng lớn nhất của dãy con tăng kết thúc tại a[i]\nbest = 0\nprint(best)",hints:["Giống LIS O(n²), chỉ thay “độ dài” bằng “tổng”: dp[i] = a[i] + max dp[j] với j < i, a[j] < a[i].","Không có j phù hợp thì dp[i] = a[i]: khởi tạo dp = a[:].","Mẹo mảng đuôi không dùng được ở đây; n ≤ 3000 nên O(n²) là vừa."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        long[] dp = new long[n];               // dp[i]: tổng lớn nhất của dãy con tăng kết thúc tại a[i]\n        long best = 0;\n        Console.WriteLine(best);\n    }\n}",hints:["Giống LIS O(n²), chỉ thay “độ dài” bằng “tổng”: dp[i] = a[i] + max dp[j] với j < i, a[j] < a[i].","Không có j phù hợp thì dp[i] = a[i].","Mẹo mảng đuôi không dùng được ở đây; n ≤ 3000 nên O(n²) là vừa. Tổng tới 3·10^12: long."]}},{t:"Dãy con tăng dài nhất",d:"Đầu vào: n (1 ≤ n ≤ 2·10^5) và n số nguyên (|aᵢ| ≤ 10^9). Đầu ra: độ dài dãy con tăng ngặt dài nhất.",tests:[{in:"8\n10 9 2 5 3 7 101 18",out:"4"},{in:"6\n0 1 0 3 2 3",out:"4"},{in:"4\n7 7 7 7",out:"1"},{in:"1\n5",out:"1"},{in:"5\n-3 -2 -1 -5 0",out:"4"},{in:"80\n-50 -9 32 -28 13 -47 -6 35 -25 16 -44 -3 38 -22 19 -41 0 41 -19 22 -38 3 44 -16 25 -35 6 47 -13 28 -32 9 50 -10 31 -29 12 -48 -7 34 -26 15 -45 -4 37 -23 18 -42 -1 40 -20 21 -39 2 43 -17 24 -36 5 46 -14 27 -33 8 49 -11 30 -30 11 -49 -8 33 -27 14 -46 -5 36 -24 17 -43",out:"17"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> d;                     // d[k]: đuôi nhỏ nhất của dãy tăng dài k + 1\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        // tìm ô đầu tiên >= x; thay ô đó, hoặc thêm vào cuối\n    }\n    cout << d.size() << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%10007).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+200,why:"Quy hoạch động O(n²) quá chậm với n = 2·10^5. Mảng đuôi + tìm kiếm nhị phân là O(n log n)."},py:{start:"from bisect import bisect_left\n\nn = int(input())\na = list(map(int, input().split()))\nd = []                         # d[k]: đuôi nhỏ nhất của dãy tăng dài k + 1\nfor x in a:\n    pass                       # tìm ô đầu tiên >= x; thay ô đó, hoặc thêm vào cuối\nprint(len(d))",hints:["Giữ d tăng dần: d[k] là đuôi nhỏ nhất của dãy con tăng dài k + 1.","bisect_left(d, x) cho ô đầu tiên ≥ x. Bằng len(d) thì append, không thì ghi đè.","Tăng ngặt nên dùng bisect_left; bisect_right sẽ đếm cả dãy có phần tử bằng nhau."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        var d = new List<int>();               // d[k]: đuôi nhỏ nhất của dãy tăng dài k + 1\n        foreach (int x in a)\n        {\n            // tìm ô đầu tiên >= x (tìm kiếm nhị phân); thay ô đó, hoặc thêm vào cuối\n        }\n        Console.WriteLine(d.Count);\n    }\n}",hints:["Giữ d tăng dần: d[k] là đuôi nhỏ nhất của dãy con tăng dài k + 1.","Tự viết tìm kiếm nhị phân “ô đầu tiên ≥ x”. Bằng d.Count thì Add, không thì ghi đè.","List.BinarySearch không đảm bảo trả về ô đầu tiên khi có phần tử bằng nhau; tự viết cho chắc."]}},{t:"Lồng phong bì",d:"Phong bì (w₁, h₁) bỏ lọt vào phong bì (w₂, h₂) khi w₁ < w₂ và h₁ < h₂ (không được xoay). Đầu vào: n (1 ≤ n ≤ 10^5), rồi n dòng wᵢ hᵢ (1 ≤ wᵢ, hᵢ ≤ 10^9). Đầu ra: số phong bì nhiều nhất lồng được vào nhau thành một chuỗi.",tests:[{in:"4\n5 4\n6 4\n6 7\n2 3",out:"3"},{in:"3\n1 1\n1 1\n1 1",out:"1"},{in:"1\n1 1",out:"1"},{in:"3\n1 3\n2 2\n3 1",out:"1"},{in:"5\n4 5\n4 6\n6 7\n2 3\n1 1",out:"4"},{in:"60\n1 1\n8 24\n15 17\n22 10\n29 3\n6 26\n13 19\n20 12\n27 5\n4 28\n11 21\n18 14\n25 7\n2 30\n9 23\n16 16\n23 9\n30 2\n7 25\n14 18\n21 11\n28 4\n5 27\n12 20\n19 13\n26 6\n3 29\n10 22\n17 15\n24 8\n1 1\n8 24\n15 17\n22 10\n29 3\n6 26\n13 19\n20 12\n27 5\n4 28\n11 21\n18 14\n25 7\n2 30\n9 23\n16 16\n23 9\n30 2\n7 25\n14 18\n21 11\n28 4\n5 27\n12 20\n19 13\n26 6\n3 29\n10 22\n17 15\n24 8",out:"2"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<pair<int,int>> p(n);\n    for (int i = 0; i < n; i++) cin >> p[i].first >> p[i].second;\n    // sắp theo w tăng dần; w bằng nhau thì h GIẢM dần; rồi tìm LIS ngặt trên h\n    vector<int> d;\n    cout << d.size() << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=0;i<n;i++)r.push(((i*7919)%1000+1)+" "+((i*104729)%1000+1));return n+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>80*n*Math.log2(n)+200,why:"Quy hoạch động O(n²) trên các phong bì đã sắp quá chậm. Đưa về LIS với mảng đuôi là O(n log n)."},py:{start:"from bisect import bisect_left\n\nn = int(input())\np = [tuple(map(int, input().split())) for _ in range(n)]\n# sắp theo w tăng dần; w bằng nhau thì h GIẢM dần; rồi tìm LIS ngặt trên h\nd = []\nprint(len(d))",hints:["Sắp theo w tăng dần thì chuỗi lồng nhau là một dãy con có h tăng ngặt: bài trở thành LIS trên h.","Hai phong bì cùng w không lồng được: sắp với key=lambda x: (x[0], -x[1]) để cùng w thì h giảm dần.","LIS bằng mảng đuôi O(n log n)."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] w = new int[n], h = new int[n], id = new int[n];\n        for (int i = 0; i < n; i++)\n        {\n            int[] t = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            w[i] = t[0]; h[i] = t[1]; id[i] = i;\n        }\n        // sắp id theo w tăng dần; w bằng nhau thì h GIẢM dần; rồi tìm LIS ngặt trên h\n        var d = new List<int>();\n        Console.WriteLine(d.Count);\n    }\n}",hints:["Sắp theo w tăng dần thì chuỗi lồng nhau là một dãy con có h tăng ngặt: bài trở thành LIS trên h.","Hai phong bì cùng w không lồng được: cùng w thì sắp h giảm dần (h[y].CompareTo(h[x])).","LIS bằng mảng đuôi O(n log n)."]}}]);

